package com.example.pryanik;

import com.sk89q.worldedit.bukkit.BukkitAdapter;
import com.sk89q.worldguard.WorldGuard;
import com.sk89q.worldguard.protection.flags.Flags;
import com.sk89q.worldguard.protection.flags.StateFlag;
import com.sk89q.worldguard.protection.managers.RegionManager;
import com.sk89q.worldguard.protection.regions.ProtectedCuboidRegion;
import java.io.File;
import java.util.*;
import org.bukkit.*;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.entity.CreatureSpawnEvent;
import org.bukkit.event.entity.EntityDamageEvent;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.player.*;
import org.bukkit.event.weather.WeatherChangeEvent;
import org.bukkit.inventory.ItemStack;

public final class GameModes implements Listener {
 private static final String LOBBY_REGION_ID="adminsrv";
 private final PryanikPlugin plugin;
 private final Map<String,String> worldToInstance=new HashMap<>();
 private final NamespacedKey compassKey;
 public void setCompassKey(NamespacedKey key){}
 public GameModes(PryanikPlugin plugin){this.plugin=plugin;this.compassKey=new NamespacedKey(plugin,GameModeCommand.SELECTOR);}
 private Location lobbySpawn(World w){return new Location(w,4.449,-58.0,21.489);}
 private boolean isLobbyWorld(World w){return w!=null&&"lobby".equalsIgnoreCase(w.getName());}
 public boolean isLobby(World w){World l=lobby();return w!=null&&l!=null&&w.equals(l);}
 public void configureLobbyWorld(World w){if(!isLobbyWorld(w))return;w.setTime(6000L);w.setStorm(false);w.setThundering(false);w.setGameRule(GameRule.DO_DAYLIGHT_CYCLE,false);w.setGameRule(GameRule.DO_WEATHER_CYCLE,false);w.setGameRule(GameRule.DO_MOB_SPAWNING,false);w.setGameRule(GameRule.DO_PATROL_SPAWNING,false);w.setGameRule(GameRule.DO_TRADER_SPAWNING,false);w.setGameRule(GameRule.DO_INSOMNIA,false);w.setGameRule(GameRule.DO_FIRE_TICK,false);w.setGameRule(GameRule.DO_IMMEDIATE_RESPAWN,true);w.setSpawnLocation(lobbySpawn(w));for(Entity e:w.getEntities())if(e instanceof LivingEntity&&!(e instanceof Player))e.remove();}
 public void configureLobbyPlayer(Player p){if(!isLobbyWorld(p.getWorld()))return;p.setGameMode(GameMode.ADVENTURE);p.setInvulnerable(true);p.setFallDistance(0);p.setFireTicks(0);p.setFoodLevel(20);p.setSaturation(20F);}
 public void configureAllLobbyPlayers(){World w=lobby();if(w==null)return;configureLobbyWorld(w);for(Player p:w.getPlayers()){configureLobbyPlayer(p);if(plugin.gameStateManager()!=null)plugin.gameStateManager().initialize(p,"lobby");}}
 public void protectLobbyOnce(){if(plugin.getConfig().getBoolean("lobby-protection.completed",false))return;World w=lobby();if(w==null){plugin.getLogger().severe("Cannot create lobby region: lobby not loaded.");return;}RegionManager m=WorldGuard.getInstance().getPlatform().getRegionContainer().get(BukkitAdapter.adapt(w));if(m==null){plugin.getLogger().severe("WorldGuard RegionManager unavailable.");return;}try{ProtectedCuboidRegion r;if(m.hasRegion(LOBBY_REGION_ID)){var old=m.getRegion(LOBBY_REGION_ID);if(!(old instanceof ProtectedCuboidRegion cuboid))throw new IllegalStateException("adminsrv exists but is not a cuboid");r=cuboid;plugin.getLogger().warning("adminsrv exists; retaining bounds.");}else{r=new ProtectedCuboidRegion(LOBBY_REGION_ID,com.sk89q.worldedit.math.BlockVector3.at(Integer.MIN_VALUE,-64,Integer.MIN_VALUE),com.sk89q.worldedit.math.BlockVector3.at(Integer.MAX_VALUE,319,Integer.MAX_VALUE));r.getOwners().addPlayer("ADMINSRV");r.setFlag(Flags.PVP,StateFlag.State.DENY);r.setPriority(1000);m.addRegion(r);}m.save();plugin.getConfig().set("lobby-protection.completed",true);plugin.saveConfig();}catch(Exception e){plugin.getLogger().severe("Failed to protect lobby: "+e.getMessage());}}
 public void refreshIndex(){worldToInstance.clear();try{Map<String,String> map=new HashMap<>();for(String[] i:plugin.db().gameInstances())map.put(i[2],i[0]+"_"+i[1]);for(String[] set:plugin.db().managedWorldSets()){String id=map.get(set[0]);if(id!=null)for(int i=1;i<=3;i++)worldToInstance.put(set[i],id);}}catch(Exception e){plugin.getLogger().warning("Could not read grief/world-set registry: "+e.getMessage());}}
 public void ensureLobby(){World w=Bukkit.getWorld("lobby");if(w==null){File f=new File(Bukkit.getWorldContainer(),"lobby");if(!new File(f,"level.dat").isFile()){plugin.getLogger().severe("Lobby folder has no level.dat: "+f);return;}try{w=Bukkit.createWorld(new WorldCreator("lobby").environment(World.Environment.NORMAL));}catch(Exception e){plugin.getLogger().severe("Could not load lobby: "+e.getMessage());return;}}if(w!=null){configureLobbyWorld(w);protectLobbyOnce();plugin.getLogger().info("Lobby ready: lobby");}}
 public String instanceOf(String name){return worldToInstance.get(name);}
 public World lobby(){return Bukkit.getWorld("lobby");}
 public int count(String mode){return switch(mode){case "survival"->20;case "anarchy"->15;case "hardcore"->5;default->0;};}
 public int capacity(String mode){return "survival".equals(mode)?20:15;}
 public boolean goTo(Player p,Location l){if(l==null||l.getWorld()==null)return false;boolean ok=p.teleport(l,PlayerTeleportEvent.TeleportCause.PLUGIN);if(!ok)p.sendMessage("§cНе удалось телепортироваться.");return ok;}
 public int online(String id){int n=0;for(Player p:Bukkit.getOnlinePlayers())if(id.equals(instanceOf(p.getWorld().getName())))n++;return n;}
 public boolean isModeWorld(World w){return w!=null&&instanceOf(w.getName())!=null;}
 public boolean canSee(Player a,Player b){if(!plugin.authed(a.getUniqueId())||!plugin.authed(b.getUniqueId()))return false;String x=instanceOf(a.getWorld().getName()),y=instanceOf(b.getWorld().getName());return x==null&&y==null||x!=null&&x.equals(y);}
 public void syncVisibility(){List<Player> all=new ArrayList<>(Bukkit.getOnlinePlayers());for(Player a:all)for(Player b:all)if(!a.equals(b)){if(canSee(a,b))a.showPlayer(plugin,b);else a.hidePlayer(plugin,b);}}
 public void goHub(Player p){World w=lobby();if(w==null){p.sendMessage("§cЛобби не загружено.");return;}if(goTo(p,lobbySpawn(w))){Bukkit.getScheduler().runTaskLater(plugin,()->{if(p.isOnline()&&isLobbyWorld(p.getWorld())){configureLobbyPlayer(p);giveLobbyCompass(p);}},2L);syncVisibility();}}
 @EventHandler public void respawn(PlayerRespawnEvent e){World from=e.getPlayer().getWorld();String id=instanceOf(from.getName());if(id!=null){if(id.startsWith("hardcore_")){World l=lobby();if(l!=null)e.setRespawnLocation(lobbySpawn(l));}else{World w=worldFor(id,from.getEnvironment());if(w!=null)e.setRespawnLocation(w.getSpawnLocation());}}else if(!isModeWorld(from)){World l=lobby();if(l!=null)e.setRespawnLocation(lobbySpawn(l));}}
 private World worldFor(String id,World.Environment env){return Bukkit.getWorld(id+(env==World.Environment.NETHER?"_nether":env==World.Environment.THE_END?"_the_end":""));}
 @EventHandler(priority=EventPriority.MONITOR) public void onDeath(PlayerDeathEvent e){String id=instanceOf(e.getEntity().getWorld().getName());if(id!=null&&id.startsWith("hardcore_")){banHardcore(e.getEntity().getUniqueId(),id);e.getEntity().sendMessage("§cВы погибли. Вход в этот хардкорный гриф заблокирован.");}}
 @EventHandler(priority=EventPriority.HIGHEST) public void blockedDeath(PlayerRespawnEvent e){String id=instanceOf(e.getPlayer().getWorld().getName());if(id!=null&&id.startsWith("hardcore_")&&isBanned(e.getPlayer().getUniqueId(),id)){World l=lobby();if(l!=null)e.setRespawnLocation(lobbySpawn(l));}}
 private boolean isBanned(UUID id,String instance){try{return plugin.db().hardcoreBanned(id,instance);}catch(Exception e){return true;}}
 public boolean mayTeleport(Player p,Location to){if(to==null)return false;String id=instanceOf(to.getWorld().getName());try{return id==null||!id.startsWith("hardcore_")||!plugin.db().hardcoreBanned(p.getUniqueId(),id);}catch(Exception e){return false;}}
 public void enter(Player p,String mode,int no){if(!isLobby(p.getWorld())||!plugin.authed(p.getUniqueId())||no<1||no>count(mode))return;String id=mode+"_"+no;try{if("hardcore".equals(mode)&&plugin.db().hardcoreBanned(p.getUniqueId(),id)){p.sendMessage("§cВход в этот хардкорный гриф запрещён.");return;}if(plugin.db().instanceNoForSet(id)>0&&online(id)>=capacity(mode)){p.sendMessage("§cЭтот гриф заполнен.");return;}String[] names={id,id+"_nether",id+"_the_end"};World.Environment[] envs={World.Environment.NORMAL,World.Environment.NETHER,World.Environment.THE_END};World target=Bukkit.getWorld(names[0]);if(target==null){boolean any=false;for(String n:names)any|=new File(Bukkit.getWorldContainer(),n).exists();if(any){for(int i=0;i<3;i++){File f=new File(Bukkit.getWorldContainer(),names[i]);if(!f.exists())continue;if(!new File(f,"level.dat").isFile())throw new IllegalStateException("existing world lacks level.dat: "+names[i]);if(Bukkit.createWorld(new WorldCreator(names[i]).environment(envs[i]))==null)throw new IllegalStateException("cannot load existing world: "+names[i]);}target=Bukkit.getWorld(names[0]);if(target==null)throw new IllegalStateException("existing overworld missing: "+names[0]);}else{for(int i=0;i<3;i++)if(Bukkit.createWorld(new WorldCreator(names[i]).environment(envs[i]))==null)throw new IllegalStateException("cannot create dimension "+names[i]);target=Bukkit.getWorld(names[0]);}plugin.db().rememberWorldSet(id,names[0],names[1],names[2]);plugin.db().registerGameInstance(mode,no,id);refreshIndex();}Location dest=target.getSpawnLocation();String[] saved=plugin.savedPosition(p.getUniqueId());if(saved!=null&&id.equals(instanceOf(saved[0]))){World sw=Bukkit.getWorld(saved[0]);if(sw!=null)dest=new Location(sw,Double.parseDouble(saved[1]),Double.parseDouble(saved[2]),Double.parseDouble(saved[3]),Float.parseFloat(saved[4]),Float.parseFloat(saved[5]));}plugin.gameStateManager().beginInstance(p,id);if(goTo(p,dest)){p.setGameMode(GameMode.SURVIVAL);p.setInvulnerable(plugin.afk(p.getUniqueId())||plugin.van(p.getUniqueId()));p.closeInventory();p.getPersistentDataContainer().remove(new NamespacedKey(plugin,GameModeCommand.KEY));p.getPersistentDataContainer().remove(new NamespacedKey(plugin,GameModeCommand.SELECTOR));p.getPersistentDataContainer().remove(new NamespacedKey(plugin,GameModeCommand.SELECTOR));plugin.db().savePosition(p.getUniqueId(),dest.getWorld().getName(),dest.getX(),dest.getY(),dest.getZ(),dest.getYaw(),dest.getPitch());p.sendMessage("§aВы вошли в гриф §e"+id+"§a.");}else plugin.gameStateManager().cancelTransition(p);}catch(Exception e){plugin.gameStateManager().cancelTransition(p);plugin.getLogger().warning("Could not enter grief "+id+": "+e.getMessage());p.sendMessage("§cНе удалось войти в гриф.");}}
 public void banHardcore(UUID id,String instance){try{plugin.db().banHardcore(id,instance);}catch(Exception e){plugin.getLogger().severe("Could not record hardcore death: "+e.getMessage());}}
 public void giveLobbyCompass(Player p){if(compassKey==null)return;ItemStack compass=GameModeCommand.compass(compassKey);for(int slot=0;slot<p.getInventory().getSize();slot++)if(GameModeCommand.isCompass(p.getInventory().getItem(slot),compassKey))return;ItemStack existing=p.getInventory().getItem(0);if(existing==null||existing.getType().isAir()){p.getInventory().setItem(0,compass);return;}for(int slot=1;slot<p.getInventory().getSize();slot++){ItemStack item=p.getInventory().getItem(slot);if(item==null||item.getType().isAir()){p.getInventory().setItem(slot,compass);return;}}p.getInventory().addItem(compass);p.sendMessage("§eИнвентарь заполнен — компас добавлен рядом.");}
 public void sendToLobby(Player p){World w=lobby();if(!p.isOnline()||w==null)return;if(goTo(p,lobbySpawn(w))){configureLobbyPlayer(p);giveLobbyCompass(p);syncVisibility();}}

  @EventHandler(priority=EventPriority.HIGHEST) public void onJoin(PlayerJoinEvent e){Player p=e.getPlayer();World w=lobby();if(w==null){p.kickPlayer("Lobby unavailable.");return;}plugin.gameStateManager().initialize(p,"lobby");Bukkit.getScheduler().runTaskLater(plugin,()->{if(!p.isOnline())return;World currentLobby=lobby();if(currentLobby==null){p.kickPlayer("Lobby unavailable.");return;}if(!isLobby(p.getWorld()))goTo(p,lobbySpawn(currentLobby));configureLobbyPlayer(p);giveLobbyCompass(p);syncVisibility();},2L);}
 @EventHandler(priority=EventPriority.MONITOR) public void saveOnWorldChange(PlayerChangedWorldEvent e){Player p=e.getPlayer();if(isLobbyWorld(p.getWorld()))configureLobbyPlayer(p);else if(isModeWorld(p.getWorld())){p.setGameMode(GameMode.SURVIVAL);p.setInvulnerable(plugin.afk(p.getUniqueId())||plugin.van(p.getUniqueId()));}}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void lobbyVoid(EntityDamageEvent e){if(e.getEntity() instanceof Player p&&isLobbyWorld(p.getWorld())){e.setCancelled(true);p.setInvulnerable(true);p.setHealth(p.getMaxHealth());p.teleport(lobbySpawn(p.getWorld()));}}
 @EventHandler(priority=EventPriority.MONITOR) public void lobbyDeath(PlayerDeathEvent e){if(isLobbyWorld(e.getEntity().getWorld()))Bukkit.getScheduler().runTask(plugin,()->{Player p=e.getEntity();if(p.isOnline()){p.spigot().respawn();Bukkit.getScheduler().runTask(plugin,()->{World w=lobby();if(w!=null){p.teleport(lobbySpawn(w));p.setHealth(p.getMaxHealth());configureLobbyPlayer(p);}});}});}
 @EventHandler(priority=EventPriority.MONITOR) public void saveOnQuit(PlayerQuitEvent e){savePosition(e.getPlayer());}
 private void savePosition(Player p){if(!isModeWorld(p.getWorld()))return;Location l=p.getLocation();try{plugin.db().savePosition(p.getUniqueId(),p.getWorld().getName(),l.getX(),l.getY(),l.getZ(),l.getYaw(),l.getPitch());}catch(Exception e){plugin.getLogger().warning("Cannot save position: "+e.getMessage());}}
 @EventHandler(priority=EventPriority.MONITOR) public void onWorldChange(PlayerChangedWorldEvent e){Player p=e.getPlayer();if(isModeWorld(p.getWorld())){plugin.restore(p);return;}configureLobbyPlayer(p);for(int i=0;i<p.getInventory().getSize();i++)if(GameModeCommand.isCompass(p.getInventory().getItem(i),compassKey))p.getInventory().setItem(i,null);if(GameModeCommand.isCompass(p.getInventory().getItemInOffHand(),compassKey))p.getInventory().setItemInOffHand(null);p.updateInventory();giveLobbyCompass(p);syncVisibility();}
 @EventHandler public void onQuit(PlayerQuitEvent e){Bukkit.getScheduler().runTask(plugin,this::syncVisibility);}
 @EventHandler public void lobbyMobSpawn(CreatureSpawnEvent e){if(isLobbyWorld(e.getLocation().getWorld()))e.setCancelled(true);}
 @EventHandler public void lobbyWeather(WeatherChangeEvent e){if(isLobbyWorld(e.getWorld())&&e.toWeatherState())e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void protectSelectorDrop(PlayerDropItemEvent e){if(isLobby(e.getPlayer().getWorld())&&GameModeCommand.isCompass(e.getItemDrop().getItemStack(),compassKey))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void lobbyDamage(EntityDamageEvent e){if(e.getEntity() instanceof Player p&&isLobbyWorld(p.getWorld())){e.setCancelled(true);p.setFireTicks(0);p.setFallDistance(0);}}
 @EventHandler(priority=EventPriority.HIGHEST) public void lobbyGamemode(PlayerGameModeChangeEvent e){if(isLobbyWorld(e.getPlayer().getWorld())&&e.getNewGameMode()!=GameMode.ADVENTURE)Bukkit.getScheduler().runTask(plugin,()->e.getPlayer().setGameMode(GameMode.ADVENTURE));}
 @EventHandler public void lobbyTick(PlayerMoveEvent e){if(isLobbyWorld(e.getPlayer().getWorld())){configureLobbyPlayer(e.getPlayer());if(e.getTo()!=null&&e.getTo().getY()<-60)e.getPlayer().teleport(lobbySpawn(e.getPlayer().getWorld()));}}
 @EventHandler public void menuGuard(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p)||isModeWorld(p.getWorld()))return;if(e.getCurrentItem()!=null&&GameModeCommand.isCompass(e.getCurrentItem(),compassKey))e.setCancelled(true);}
 @EventHandler(priority=EventPriority.HIGHEST) public void linkedPortals(PlayerPortalEvent e){String id=instanceOf(e.getFrom().getWorld().getName());if(id==null)return;World.Environment env=e.getFrom().getWorld().getEnvironment();if(e.getCause()==PlayerTeleportEvent.TeleportCause.NETHER_PORTAL){World w=env==World.Environment.NORMAL?Bukkit.getWorld(id+"_nether"):env==World.Environment.NETHER?Bukkit.getWorld(id):null;if(w!=null)e.setTo(new Location(w,e.getTo().getX(),e.getTo().getY(),e.getTo().getZ(),e.getTo().getYaw(),e.getTo().getPitch()));}else if(e.getCause()==PlayerTeleportEvent.TeleportCause.END_PORTAL){World w=env==World.Environment.THE_END?Bukkit.getWorld(id):Bukkit.getWorld(id+"_the_end");if(w!=null)e.setTo(new Location(w,e.getTo().getX(),e.getTo().getY(),e.getTo().getZ(),e.getTo().getYaw(),e.getTo().getPitch()));}}
}
